    [/^(.+) already exists on this project\. Open it and use “Start new revision”, or choose another number\.$/, (m) => m[1] + " មានរួចហើយនៅក្នុងគម្រោងនេះ។ សូមបើកវា ហើយប្រើ “ចាប់ផ្តើមកំណែថ្មី” ឬជ្រើសលេខផ្សេង។"],
    [/^· (.+)$/, (m, tr) => { const x = tr(m[1]); return x == null ? null : "· " + x; }],
    // Texts made of parts joined by " · " (for example "On site · 35 m"): each part is translated on its own
    [/ · /, (m, tr) => { const parts = m.input.split(" · "); let any = false; const out = parts.map((p) => { const x = tr(p); if (x != null) { any = true; return x; } const d = date(p); if (d !== p) { any = true; return d; } return p; }); return any ? out.join(" · ") : null; }],
    [/ → /, (m, tr) => { const parts = m.input.split(" → "); let any = false; const out = parts.map((p) => { const x = tr(p); if (x != null) { any = true; return x; } return p; }); return any ? out.join(" → ") : null; }],
    [/^(.+), (.+)$/, (m, tr) => { const a = tr(m[1]), b = tr(m[2]); return a != null && b != null ? a + ", " + b : null; }]
